def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    # Read the objects top-to-bottom in the left panel, then the right panel.
    objects = []
    for c0 in (0, 4):
        r = 0
        while r < h:
            while r < h and not any(grid[r][c] != 0 for c in range(c0, c0 + 3)):
                r += 1
            if r == h:
                break
            colors = set()
            while r < h and any(grid[r][c] != 0 for c in range(c0, c0 + 3)):
                colors.update(grid[r][c] for c in range(c0, c0 + 3) if grid[r][c] != 0)
                r += 1
            if colors:
                objects.append(next(iter(colors)))

    marker = next(
        ((r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5),
        (0, 8)
    )
    y, x = marker[0], marker[1] - 8
    if 0 <= y < h and 0 <= x < 7:
        out[y][x] = 5

    for color in objects:
        if color == 1:       # rightward horizontal segment, length 3
            yy = y + 1
            for c in range(x, x + 3):
                if 0 <= yy < h and 0 <= c < 7:
                    out[yy][c] = color
            x += 2
            y += 1
        elif color == 2:     # leftward horizontal segment, length 2
            yy = y + 1
            for c in range(x - 1, x + 1):
                if 0 <= yy < h and 0 <= c < 7:
                    out[yy][c] = color
            x -= 1
            y += 1
        elif color == 3:     # leftward horizontal segment, length 4
            yy = y + 1
            for c in range(x - 3, x + 1):
                if 0 <= yy < h and 0 <= c < 7:
                    out[yy][c] = color
            x -= 3
            y += 1
        elif color == 6:     # downward vertical segment, length 2
            for yy in (y + 1, y + 2):
                if 0 <= yy < h and 0 <= x < 7:
                    out[yy][x] = color
            y += 2

    return out
